#include "model.hpp"
#include <iostream>
#include <vector>
int main() {
    int n;
    if (!(std::cin >> n) || n < 0 || n > 12) {
        std::cout << "invalid\n";
        return 0;
    }
    std::vector<int> commands(n);
    for (int &x : commands) {
        if (!(std::cin >> x)) {
            std::cout << "invalid\n";
            return 0;
        }
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) {
        std::cout << "invalid\n";
        return 0;
    }
    Board board;
    int rejected = 0;
    for (int command : commands) {
        if (!board.apply(command)) {
            ++rejected;
        }
    }
    std::cout << "tasks " << board.count() << " done " << board.done()
              << " rejected " << rejected << '\n';
}

